public static int calculateFactorial(int n) {
    // 1. THE BASE CASE (The Stop Switch)
    if (n == 1) {
        return 1;
    }
    // 2. THE RECURSIVE CASE (Calling itself)
    else {
        return n * calculateFactorial(n - 1);
    }
}

