// Notice the three dots (...). This means 'zero or more integers'
public static void calculateTotal(int... prices) {
    int sum = 0;
    // Inside the method, 'prices' is treated exactly like an int[] array
    for (int price : prices) {
        sum += price;
    }
    System.out.println("Total: " + sum);
}

public static void main(String[] args) {
    calculateTotal(10, 20);         // Passes 2 arguments
    calculateTotal(5, 15, 25, 30);  // Passes 4 arguments
    calculateTotal();               // Passes 0 arguments (Empty array!)
}

