/**
 * Calculates the final grade of a student based on standard curves.
 * This method ensures no grade drops below 0 or exceeds 100.
 * 
 * @param rawScore   The original integer score the student received.
 * @param curveValue The amount of bonus points to apply.
 * @return           The finalized double-precision grade.
 */
public static double calculateFinalGrade(int rawScore, int curveValue) {
    int finalScore = rawScore + curveValue;
    return (double) finalScore;
}
